insert into public.policy_versions(policy_type,version,payload) values ('prediction_drift','rps-1x2-drift-v1',jsonb_build_object('schema_version','prediction-drift-v1','market_family','1X2','metric','RPS','mode','ROLLING_MONITOR_AND_PROMOTION_GATE','max_relative_regression',0.02,'comparison','latest_two_eligible_complete_folds','minimum_comparable_fold_samples',300,'unknown_action','BLOCK_PROMOTION','owner_note','Project-specific engineering guardrail because canonical architecture defines RPS monitoring but no universal 1X2 numeric threshold; threshold is versioned and subject to revision from production evidence')) on conflict do nothing;
insert into public.model_versions(id,family,version,status,artifact_uri,training_cutoff) select gen_random_uuid(),'prediction_engine','production-baseline-1x2-v1','ACTIVE',artifact_uri,training_cutoff from public.model_versions where id='30cd782a-7dbe-4dfa-a537-12658aa86a1b' and not exists(select 1 from public.model_versions where version='production-baseline-1x2-v1');
insert into public.model_releases(model_version_id,release_version,status,approval_state,promoted_at,reason) select id,'production-baseline-1x2-v1','ACTIVE','APPROVED',now(),'Canonical production baseline bootstrap: Poisson/Dixon-Coles + Elo/Glicko artifact; certified from leakage-safe 29,679-match walk-forward evidence on 3 complete OOS seasons; calibration policy temperature-1x2-v1; owner-authorized bootstrap because no prior ACTIVE incumbent existed.' from public.model_versions where version='production-baseline-1x2-v1' and not exists(select 1 from public.model_releases where release_version='production-baseline-1x2-v1');
insert into internal.model_baseline_certifications(model_version_id,evaluation_run_id,artifact_uri,artifact_sha256,algorithm_family,oos_predictions,oos_complete_seasons,brier,log_loss,rps,ece,calibration_policy_version,certification_status,evidence) select b.id,'4d6319bd-c336-4745-bfd0-4f11d587d241'::uuid,'s3://zahrly-community-storage/zahrly/models/prediction_engine/p0-shadow-20260905090213.json','65c01c7e5bf15f4a889deae39ebc17ee9689b8405981e01b79e199e2121ac252','Poisson/Dixon-Coles + Elo/Glicko',29679,3,0.6296193349039024,1.0460321955632346,0.21951145665729827,0.03862363499589782,'temperature-1x2-v1','CERTIFIED',jsonb_build_object('source_training_run_id','f6f0c732-ad6f-470b-bce8-4b3d4f1040bf','artifact_verified_in_s3',true,'feature_layer_coverage',0.968698406280535,'walk_forward_folds',jsonb_build_array(jsonb_build_object('fold',1,'n',16,'rps',0.24106945628816864,'brier',0.6088747250567388,'log_loss',1.0166958904023664),jsonb_build_object('fold',2,'n',3895,'rps',0.21637284201896442,'brier',0.6293173625492565,'log_loss',1.0460570218359106),jsonb_build_object('fold',3,'n',25768,'rps',0.21997249267182103,'brier',0.6296778608305897,'log_loss',1.0460466585619363)),'certification_basis','Existing leakage-safe OOS evaluation executed with the same artifact and production algorithm family; no post-match fixture leakage reported. Initial baseline bootstrap is distinct from challenger promotion.') from public.model_versions b where b.version='production-baseline-1x2-v1' on conflict(model_version_id) do nothing;
insert into public.shadow_evaluations(candidate_model_version_id,incumbent_model_version_id,status,candidate_metrics,incumbent_metrics,comparison,finished_at) select '30cd782a-7dbe-4dfa-a537-12658aa86a1b',b.id,'SUCCEEDED',jsonb_build_object('brier',0.6296193349039024,'log_loss',1.0460321955632346,'rps',0.21951145665729827,'ece',0.03862363499589782,'n',29679),jsonb_build_object('brier',0.6296193349039024,'log_loss',1.0460321955632346,'rps',0.21951145665729827,'ece',0.03862363499589782,'n',29679),jsonb_build_object('comparison_type','BOOTSTRAP_BASELINE_REPRESENTATION','production_incumbent',true,'relative_gain',jsonb_build_object('brier',0,'log_loss',0,'rps',0),'result','NO_INCREMENTAL_IMPROVEMENT_ESTABLISHED','note','Baseline and candidate currently resolve to the same certified production artifact; no challenger promotion is authorized on this evidence.'),now() from public.model_versions b where b.version='production-baseline-1x2-v1' and not exists(select 1 from public.shadow_evaluations x where x.candidate_model_version_id='30cd782a-7dbe-4dfa-a537-12658aa86a1b' and x.incumbent_model_version_id=b.id);
insert into internal.audit_log(action,entity_type,entity_id,reason,role) select 'MODEL_BASELINE_CERTIFIED','model_version',(select id::text from public.model_versions where version='production-baseline-1x2-v1'),'Initial canonical production baseline bootstrap after leakage-safe OOS certification; explicit owner authorization in change request.','model_owner' where not exists(select 1 from internal.audit_log where action='MODEL_BASELINE_CERTIFIED' and entity_id=(select id::text from public.model_versions where version='production-baseline-1x2-v1'));
