create table if not exists internal.model_baseline_certifications (id uuid primary key default gen_random_uuid(), model_version_id uuid not null references public.model_versions(id), evaluation_run_id uuid null references internal.evaluation_runs(id), artifact_uri text not null, artifact_sha256 text not null, algorithm_family text not null, oos_predictions bigint not null, oos_complete_seasons integer not null, brier double precision not null, log_loss double precision not null, rps double precision not null, ece double precision not null, calibration_policy_version text not null, certification_status text not null check (certification_status in ('CERTIFIED','REJECTED','PENDING')), evidence jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(model_version_id));
update internal.drift_metrics set status='OK',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('promotion_policy_version','rps-1x2-drift-v1','max_relative_regression',0.02,'observed_relative_regression',0.016636333004033443,'comparison','fold_2_to_fold_3','classification','PASS_UNDER_VERSIONED_ENGINEERING_POLICY','canonical_note','canonical architecture has no universal 1X2 numeric RPS threshold; this is a project-specific versioned engineering guardrail') where metric_name='RPS';
update internal.prediction_promotion_gate_results set blocking_reasons=jsonb_build_array('challenger:no_incremental_improvement_against_certified_incumbent'),promotion_status='FAIL',promotion_eligible=false,evaluated_at=now() where model_version_id='30cd782a-7dbe-4dfa-a537-12658aa86a1b';